        const void* data[]={rest.data(),membranes.data(),hinges.data(),schedule.data(),adjacency.data(),colliders.data()};for(unsigned i=0;i<6;++i){void* mapped=nullptr;D3D12_RANGE none{0,0};check(resources[i+6].p->Map(0,&none,&mapped),"Map immutable cloth topology");std::memcpy(mapped,data[i],sizes[i+6]);D3D12_RANGE written{0,static_cast<SIZE_T>(sizes[i+6])};resources[i+6].p->Unmap(0,&written);}
